#!/usr/bin/env node
import fs from "fs-extra";
import path from "path";
import archiver from "archiver";
import chalk from "chalk";
import { program } from "commander";
program
    .option("-d, --dist <dir>", "Directory to package (must contain metadata.json)", "dist")
    .option("-o, --output <dir>", "Output directory for the ZIP file", "build")
    .option("--quiet", "Suppress most output")
    .option("--verbose", "Verbose logs");
program.parse(process.argv);
const opts = program.opts();
function logInfo(msg) {
    if (!opts.quiet)
        console.log(`[${chalk.blue("INFO")}] ${msg}`);
}
function logSuccess(msg) {
    if (!opts.quiet)
        console.log(`[${chalk.blue("INFO")}] ${msg}`);
}
function logWarn(msg) {
    if (!opts.quiet)
        console.log(`[${chalk.yellow("WARN")}] ${msg}`);
}
function logError(msg) {
    console.error(`[${chalk.red("ERROR")}] ${msg}`);
}
async function buildPlugin() {
    const distDir = path.resolve(opts.dist);
    const outDir = path.resolve(opts.output);
    // 1. Ensure distDir exists and is not empty
    if (!fs.existsSync(distDir)) {
        logError(`Directory ${distDir} does not exist.`);
        process.exit(1);
    }
    const files = await fs.readdir(distDir);
    if (files.length === 0) {
        logError(`Directory ${distDir} is empty. Nothing to package.`);
        process.exit(1);
    }
    // 2. Validate that metadata.json exists in distDir
    const metadataPath = path.join(distDir, "metadata.json");
    if (!fs.existsSync(metadataPath)) {
        logError(`metadata.json not found in ${distDir}/. Please build the plugin first.`);
        process.exit(1);
    }
    const metadata = await fs.readJson(metadataPath);
    const pluginId = metadata.id || "plugin";
    const version = metadata.version || "0.0.0";
    const finalId = `${metadata.publisher.id}.${metadata.id}`;
    logInfo(`Building plugin ${chalk.cyan(pluginId)} v${version} ${chalk.gray(`[${finalId}]`)}`);
    // 3. Validate entryPoints from metadata.json
    if (!metadata.entryPoints || typeof metadata.entryPoints !== "object") {
        logError("No entryPoints defined in metadata.json");
        process.exit(1);
    }
    const entryFiles = Object.values(metadata.entryPoints);
    for (const file of entryFiles) {
        const filePath = path.join(distDir, file);
        if (!fs.existsSync(filePath)) {
            logError(`Entry point not found: ${file} (expected at ${opts.dist}/${file})`);
            process.exit(1);
        }
        logInfo(`Found entrypoint: ${file}`);
    }
    // 4. Ensure output directory exists
    await fs.ensureDir(outDir);
    // 5. Package all contents of distDir into a zip file
    const zipName = `${pluginId}-${version}.zip`;
    const zipPath = path.join(outDir, zipName);
    logInfo(`Packaging all files in ${distDir}/ to ${chalk.magenta(zipPath)}`);
    await new Promise((resolve, reject) => {
        const output = fs.createWriteStream(zipPath);
        const archive = archiver("zip", { zlib: { level: 9 } });
        output.on("close", () => {
            logSuccess(`Plugin ${chalk.green("build successfully")} at: ${zipPath} ${chalk.gray(`(${(archive.pointer() / 1024).toFixed(1)} KB)`)}`);
            resolve();
        });
        archive.on("error", (err) => {
            logError(`Failed to create ZIP: ${err}`);
            reject(err);
        });
        archive.pipe(output);
        // Add all files and subfolders of distDir (non-recursive means "false" here)
        archive.directory(distDir, false);
        archive.finalize();
    });
}
buildPlugin().catch((err) => {
    logError("Unexpected error during build:");
    if (opts.verbose) {
        console.error(err);
    }
    process.exit(1);
});
